// What a Google booking actually says, pulled out of the shape Google stores it in.
//
// Two things are wanted: who booked, and the code they typed. Both are in the event, and both are
// in more than one place, which is the trap.
//
// The email is taken from the attendee list and never from the description. The description is
// prose Google assembles, and it is written in the language of whoever is doing the booking: the
// same booking page produced "Zarezerwowane przez" for one booking and "Booked by" for the next,
// because a setting changed between them. Any rule keyed on those words breaks the day somebody
// books from a different country.
//
// The code survives that, because the label is ours: "Order code" is what the booking form was
// told to call the question, so it is the same string in every language Google renders around it.

const TAGS = /<br\s*\/?>|<\/?[a-z][^>]*>/gi;

const plain = (html) => String(html || '')
  .replace(TAGS, '\n')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ').replace(/&#39;/g, "'").replace(/&quot;/g, '"');

// Every question this booking form asks. Needed here rather than only at the call sites, because
// the answer to one is found by knowing where the next begins.
const LABELS = ['Booked by', 'Order code', 'Street address', 'City', 'ZIP code'];

// The answer is the first non-empty line after the label -- Google lays them out as label, newline,
// answer, with blank lines between from the markup.
//
// Unless that line is the next question. A form answer left blank leaves its label with nothing
// under it, and taking the next non-empty line then reaches past the gap and picks up the following
// label as though somebody had typed it: a blank street becomes "City", which is then written to
// the job and printed on the page a customer signs. Blank has to come back as blank.
const answerTo = (description, label) => {
  const lines = plain(description).split('\n').map((line) => line.trim());
  const at = lines.findIndex((line) => line.toLowerCase() === label.toLowerCase());
  if (at === -1) return null;
  const said = lines.slice(at + 1).find((line) => line !== '');
  if (!said) return null;
  const isAnotherQuestion = LABELS.some((l) => l.toLowerCase() === said.toLowerCase());
  return isAnotherQuestion ? null : said;
};

// Where the work is, asked on the booking form rather than read out of a letter. A customer writes
// "Kyle TX" in an email and means one of several places; here they type it with the deed in front
// of them, and the answer is theirs rather than something extracted from prose.
//
// Three questions rather than one, because somebody given a single box writes "123 Oak St" and
// stops -- and a street with no town is not somewhere anybody can drive to. The postcode earns its
// place separately: the service area is kept by postcode as well as by name, so this is the one
// form of the address the desk can check rather than believe.
//
// Labels are ours, so they survive whatever language Google renders the rest of the page in --
// the same reason the code can be read from here and the guest's email cannot.
const oneLine = (said) => (said ? String(said).replace(/\s+/g, ' ').trim() : null) || null;

// A code is worth nothing unless it is one we could have issued. Accepting anything typed lets a
// stray word match nothing slowly instead of nothing quickly, and puts junk in the logs.
//
// Five letters then two digits, with no separator in the issued form -- but people type what looks
// right to them, so spaces, hyphens and dots are taken out before the shape is checked. Somebody
// writing "kqmnp 47" has done nothing wrong and should not lose their booking over it.
const CODE = /^[ABCDEFGHJKMNPQRSTUVWXYZ]{5}[23456789]{2}$/;
const tidy = (typed) => String(typed || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

return $input.all().map((item, i) => {
  const event = item.json || {};
  const organiser = String(event.organizer?.email || '').toLowerCase();
  const attendees = Array.isArray(event.attendees) ? event.attendees : [];

  // the one who is not us. An appointment schedule puts the desk on every booking as organiser,
  // so the guest is whoever is left.
  const guest = attendees
    .map((a) => String(a.email || '').toLowerCase())
    .find((email) => email && email !== organiser) || null;

  const typed = answerTo(event.description, 'Order code');
  const cleaned = tidy(typed);
  const code = CODE.test(cleaned) ? cleaned : null;

  return {
    json: {
      event_id: event.id || null,
      booked_email: guest,
      booking_code: code,
      code_as_typed: typed,
      site_street: oneLine(answerTo(event.description, 'Street address')),
      site_city: oneLine(answerTo(event.description, 'City')),
      site_postcode: oneLine(answerTo(event.description, 'ZIP code')),
      starts_at: event.start?.dateTime || null,
      time_zone: event.start?.timeZone || null,
      summary: event.summary || null,
      // nothing to look a job up by at all. Said here rather than discovered by two queries that
      // both return nothing.
      nothing_to_go_on: !guest && !code,
    },
    pairedItem: { item: i },
  };
});

// The letter that says a booking landed on a job, written a quarter of an hour after it did.
//
// Google has already sent its own confirmation with the time in it. This one says what Google
// cannot: which job this visit is for, what the desk has on it so far, and that the customer can
// correct any of it by replying. Repeating the time as well is deliberate -- it is the one fact
// both letters carry, and it is how a customer knows the two are about the same thing.
//
// The time is rendered in Texas. It was stored as an instant, and an instant printed in the wrong
// place is a wrong time: the same booking read half past eight in the evening to somebody sitting
// in Warsaw and half past one in the afternoon to the person driving to it.
const WHERE_THE_WORK_IS = 'America/Chicago';

const when = (iso) => {
  const at = new Date(iso);
  if (Number.isNaN(at.getTime())) return null;
  const day = at.toLocaleDateString('en-US', {
    timeZone: WHERE_THE_WORK_IS, weekday: 'long', month: 'long', day: 'numeric',
  });
  const time = at.toLocaleTimeString('en-US', {
    timeZone: WHERE_THE_WORK_IS, hour: 'numeric', minute: '2-digit',
  }).toLowerCase().replace(/\s/g, '');
  return `${day} at ${time}`;
};

const number = (n) => Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 });

// What the desk has on the job, in the customer's own terms. Only what is actually known: a line
// saying "area: not said yet" tells them nothing and reads as a form they failed to fill in.
const theJob = (row) => {
  const lines = [];
  if (row.material_category) lines.push(`  Floor: ${row.material_category}`);
  if (row.area_sqft) lines.push(`  Area: about ${number(row.area_sqft)} ${row.area_unit || 'sqft'}`);
  if (row.city) lines.push(`  Where: ${row.city}`);
  const onSite = Array.isArray(row.on_site_items) ? row.on_site_items : [];
  if (onSite.length) lines.push(`  To measure on the day: ${onSite.join(', ')}`);
  return lines;
};

return $input.all().map((item, i) => {
  const row = item.json || {};
  const at = when(row.agreed);

  // a visit with no readable time is not something to write a letter about. It cannot happen from
  // the booking lane, which takes the time from Google, and saying so beats sending "undefined".
  if (!at || !row.write_to) {
    return {
      json: { ...row, ready_to_send: false,
        why_not: !at ? 'the visit has no readable time' : 'the job has no address to write to' },
      pairedItem: { item: i },
    };
  }

  const job = theJob(row);
  const body = [
    row.opening,
    '',
    `  ${at}`,
    ...(job.length ? ['', ...job] : []),
    '',
    row.closing,
    row.signature,
  ].join('\n');

  return {
    json: {
      ...row,
      ready_to_send: true,
      why_not: null,
      subject: `Visit booked — ${at}`,
      body,
    },
    pairedItem: { item: i },
  };
});

// What the calendar says about visits this database still believes in.
//
// Bookings move and bookings vanish, and neither arrives as a message anybody sends us. A customer
// presses "reschedule" on Google's own page and the desk is told nothing; the owner deletes a
// morning from her calendar and the desk is told nothing. Either way the row here goes on naming a
// time nobody is coming at, which is worse than knowing nothing: it reads as certainty.
//
// This compares the two rather than trusting a trigger to say what changed. Which events Google
// emits for a reschedule -- one updated, or a cancelled and a created -- is not something this has
// to know, and not knowing it is the point: a comparison is right whatever the notification did.

const CANCELLED = 'cancelled';

return (() => {
  const believed = $('Visits worth checking').all().map((item) => item.json || {});
  if (!believed.length) return [];

  const live = new Map();
  for (const item of $input.all()) {
    const event = item.json || {};
    if (event.id) live.set(event.id, event);
  }

  const verdicts = [];
  for (const [i, visit] of believed.entries()) {
    const event = live.get(visit.booked_event_id);

    // Not in the window we asked for is not the same as cancelled. The read covers a stretch of
    // time; a visit outside it is simply unmentioned, and calling that a cancellation would strike
    // out every booking far enough ahead.
    if (!event) continue;

    if (event.status === CANCELLED) {
      verdicts.push({ json: { ...visit, what_changed: 'gone', now_at: null }, pairedItem: { item: i } });
      continue;
    }

    const now_at = event.start?.dateTime || null;
    if (!now_at) continue;

    // compared as instants, because the two sides write the same moment differently: the database
    // hands back +00:00 and Google says -05:00, and as strings those never agree
    const same = new Date(now_at).getTime() === new Date(visit.agreed).getTime();
    if (!same) {
      verdicts.push({ json: { ...visit, what_changed: 'moved', now_at }, pairedItem: { item: i } });
    }
  }
  return verdicts;
})();

// What whoever drives out reads before knocking on the door.
//
// A message rather than a file, and not to the mailbox every customer writes to. Somebody about to
// knock is holding a phone, not opening a drive, and a note that lands among the day's letters is
// competing with the work for attention. This goes to its own channel and stays there.
//
// It is for the owner and never for the customer. It says what was quoted and calls it a ballpark,
// it names what only the visit can settle and what this firm charges for those, and it says what to
// bring. A customer reading it would learn what the firm charges itself and what it is unsure of,
// neither of which is theirs to see.
//
// Built from the job rather than from the newest letter, for the same reason everything else here
// is: a customer says "laminate, Kyle TX" one day and "about 400 sq ft" the next, and a message
// made from either letter alone sends somebody out knowing half of it.

const WHERE_THE_WORK_IS = 'America/Chicago';

const when = (iso) => {
  const at = new Date(iso);
  if (Number.isNaN(at.getTime())) return null;
  const day = at.toLocaleDateString('en-US', {
    timeZone: WHERE_THE_WORK_IS, weekday: 'long', month: 'long', day: 'numeric',
  });
  const time = at.toLocaleTimeString('en-US', {
    timeZone: WHERE_THE_WORK_IS, hour: 'numeric', minute: '2-digit',
  }).toLowerCase().replace(/\s/g, '');
  return `${day}, ${time}`;
};

const money = (n) => `$${Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 })}`;
const number = (n) => Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 });

const SPELLED = {
  remove_first: 'the old floor comes out',
  over_existing: 'laying over what is there',
};

// What to bring, worked out from the job rather than printed the same every time. A list that never
// changes is a list nobody reads by the third visit.
const toBring = (row, onSite) => {
  const bring = ['tape measure', 'moisture meter'];
  if (row.material_category) bring.push(`${row.material_category} samples`);
  if (onSite.includes('subfloor')) bring.push('levelling compound sample', 'straightedge');
  if (onSite.includes('stairs')) bring.push('tread gauge');
  if (row.old_floor_removal === true) bring.push('a look under a corner of the old floor');
  return bring;
};

return $input.all().map((item, i) => {
  const row = item.json || {};
  const at = when(row.agreed);
  const onSite = Array.isArray(row.on_site_items) ? row.on_site_items : [];
  const rates = row.on_site_rates && typeof row.on_site_rates === 'object' ? row.on_site_rates : {};
  const ballpark = row.ballpark && typeof row.ballpark === 'object' ? row.ballpark : null;

  if (!row.visit_id || !at) {
    return {
      json: { ...row, ready_to_tell: false, why_not: 'the visit has no readable time' },
      pairedItem: { item: i },
    };
  }

  // The address the customer typed on the booking form, and the city off the job only when they
  // have not booked yet. A town on its own is not somewhere anybody can drive to, and until this
  // was asked for on the form it was all the desk had.
  const booked = [row.site_street, row.site_city, row.site_postcode].filter(Boolean).join(', ');
  const where = booked
    || `${row.city || 'somewhere not established'}${row.zone ? ` (${row.zone} of the service area)` : ''}`;

  const job = [
    row.material_category || 'floor not said yet',
    row.area_sqft ? `about ${number(row.area_sqft)} ${row.area_unit || 'sqft'}`
      : 'no size given — measure everything',
    row.existing_floor_action
      ? (SPELLED[row.existing_floor_action] || row.existing_floor_action)
      : 'what happens to the old floor is not established',
    row.fixing_method || null,
  ].filter(Boolean).join(', ');

  // What was quoted, and that it was a ballpark. Somebody standing in the room needs to know what
  // the customer already has in mind before saying a firm number out loud. It is here and nowhere
  // near the agreement, which is the customer's and carries only the price agreed at the door.
  const quoted = ballpark && ballpark.low !== null && ballpark.low !== undefined
    ? `${money(ballpark.low)} to ${money(ballpark.high)}`
      + ' — a ballpark, not a commitment. The firm price is yours to give on the day.'
    : 'nothing yet.';

  const settleHere = onSite.map((thing) => {
    const rate = rates[thing];
    const range = rate ? ` — ${money(rate.val_low)} to ${money(rate.val_high)} per ${rate.unit}` : '';
    return `• ${thing}${range} — named to the customer, not counted`;
  });

  // Written to be found rather than read: these arrive one after another in a channel, and until
  // they had a heading and headed sections two of them ran together into one wall of sentences with
  // no visible seam. The first line is the one somebody reads standing up.
  const message = [
    `📋 *Job ${row.order_id} — ${at}*`,
    `📍 ${where}`,
    `✉️ ${row.contact_email || 'no address'}${row.booking_code ? `  ·  code \`${row.booking_code}\`` : ''}`,
    '',
    '*The job*',
    job,
    '',
    '*Quoted by email*',
    quoted,
    ...(settleHere.length ? ['', '*To settle on site*', ...settleHere] : []),
    '',
    '*Bring*',
    toBring(row, onSite).join(', '),
    // The page to sign, from the same message. The two were built apart and knew nothing of each
    // other: a briefing arrived, and the document sat on a drive somewhere to be hunted for.
    ...(row.agreement_url ? ['', `📄 <${row.agreement_url}|The page to sign at the door>`] : []),
  ].join('\n');

  return {
    json: { ...row, ready_to_tell: true, why_not: null, message },
    pairedItem: { item: i },
  };
});

// What goes into the copy of the agreement that is printed for a visit.
//
// The document itself is the owner's, written and formatted by hand; this only says what each
// {{placeholder}} in it becomes. Nothing here composes prose — a change to the wording of the
// agreement is a change to that document and never to this file, which is the whole reason it is a
// document rather than a template in the database.
//
// Everything is read off the job rather than the newest letter, and everything that is not known is
// said as words rather than left blank: a printed page reading "not said yet" is a page somebody
// fills in at the door, and a blank is a page nobody notices is incomplete.
//
// No price appears here at all. The ballpark belongs in what the owner is told; the only figure on
// the page a customer signs is written on it by hand after the floor has been measured.

const WHERE_THE_WORK_IS = 'America/Chicago';

const when = (iso) => {
  const at = new Date(iso);
  if (Number.isNaN(at.getTime())) return null;
  const day = at.toLocaleDateString('en-US', {
    timeZone: WHERE_THE_WORK_IS, weekday: 'long', month: 'long', day: 'numeric', year: 'numeric',
  });
  const time = at.toLocaleTimeString('en-US', {
    timeZone: WHERE_THE_WORK_IS, hour: 'numeric', minute: '2-digit',
  }).toLowerCase().replace(/\s/g, '');
  return `${day}, ${time}`;
};

const number = (n) => Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 });

const SPELLED = {
  remove_first: 'the old floor is taken out first',
  over_existing: 'the new floor goes over what is there',
};

// What the visit has to settle, in words a customer reads on the page they sign. The rates for
// these are the owner's business and stay out of it.
const SPELLED_ON_SITE = {
  stairs: 'the stairs',
  subfloor: 'what is under the old floor',
};

return $input.all().map((item, i) => {
  const row = item.json || {};
  const at = when(row.agreed);
  const onSite = Array.isArray(row.on_site_items) ? row.on_site_items : [];

  if (!row.visit_id || !at || !row.template_id) {
    return {
      json: {
        ...row,
        ready_to_prepare: false,
        why_not: !row.template_id
          ? 'there is no agreement template to copy'
          : 'the visit has no readable time',
      },
      pairedItem: { item: i },
    };
  }

  const replacements = {
    customer_email: row.contact_email || 'not established',
    job_number: String(row.order_id),
    booking_code: row.booking_code || 'not established',
    visit_date: at,
    // Both of these come off the booking form before they come off a letter. The city extracted
    // from prose and the address typed with the deed in hand can disagree, and a page that names
    // one town in one line and another in the next is a page somebody argues with at the door.
    city: row.site_city || row.city || 'not established',
    address: [row.site_street, row.site_postcode].filter(Boolean).join(', ')
      || 'to be written in below',
    material: row.material_category || 'not said yet',
    area_discussed: row.area_sqft
      ? `about ${number(row.area_sqft)} ${row.area_unit || 'sqft'}`
      : 'not given yet',
    existing_floor: row.existing_floor_action
      ? (SPELLED[row.existing_floor_action] || row.existing_floor_action)
      : 'to be decided on site',
    settled_on_site: onSite.length
      ? onSite.map((thing) => SPELLED_ON_SITE[thing] || thing).join(', ')
      : 'nothing outstanding — everything was measurable from the email',
  };

  // The job and the date, so a folder of these is readable without opening any of them, and a copy
  // left behind by a visit that moved is obvious beside the one that replaced it.
  const fileName = `Agreement — job ${row.order_id} — ${at.split(',')[1].trim()} ${at.split(',')[2].trim()}`;

  return {
    json: {
      ...row,
      ready_to_prepare: true,
      why_not: null,
      file_name: fileName,
      replacements,
      // what the Docs API is asked to do, one replacement per placeholder, built here so the node
      // carries no knowledge of what the document says
      requests: Object.entries(replacements).map(([key, value]) => ({
        replaceAllText: {
          containsText: { text: `{{${key}}}`, matchCase: true },
          replaceText: String(value),
        },
      })),
    },
    pairedItem: { item: i },
  };
});

// Whether every placeholder in the copy was actually filled.
//
// The document is the owner's and they edit it. Rename {{material}} in it, or delete the line it
// sits on, and nothing anywhere fails: the copy is made, the replacement finds no such text, and a
// customer is handed a page with {{material}} printed on it, or with a fact silently missing from
// it. That is the failure this exists for, and it is invisible from every other angle.
//
// Google answers a batch of replacements with one reply each, saying how many occurrences it
// changed. Nought means the placeholder this asked for is not in that document.

// Paired by position, never by $('...').item. This node runs over every waiting visit at once, and
// a linked item is one item: two visits in a run would both be checked against the first one's
// placeholders and both stamped against the first one's visit. Position is what pairs them, because
// the copy and the fill preserve the order the statement returned.
const prepared = $('Write the agreement').all();

return $input.all().map((item, i) => {
  const answer = item.json || {};
  const mine = prepared[i]?.json || {};
  const wanted = (mine.requests || []).map((r) => r.replaceAllText.containsText.text);
  const replies = Array.isArray(answer.replies) ? answer.replies : [];

  // A reply carries no count at all when nothing changed, so absent and nought are the same thing.
  const landed = replies.map((r) => Number(r?.replaceAllText?.occurrencesChanged || 0));
  const missing = wanted.filter((_, n) => !(landed[n] > 0));

  if (missing.length) {
    throw new Error(`the agreement for visit ${mine.visit_id} was `
      + `copied with ${missing.length} placeholder(s) unfilled: ${missing.join(', ')}. `
      + 'Either the template no longer contains them, or they are spelled differently in it. '
      + 'The copy is on Drive and is not fit to print.');
  }

  // The address of the copy, built from the id Google answered with rather than from anything this
  // lane carried in: what is stamped against the visit has to be the document that was actually
  // written to, not the one it was asked to write to.
  return {
    json: {
      ...answer,
      visit_id: mine.visit_id,
      order_id: mine.order_id,
      // carried through so the stamp can refuse a visit that moved while this was being made
      agreed: mine.agreed,
      filled: wanted.length,
      agreement_url: `https://docs.google.com/document/d/${answer.documentId}/edit`,
    },
    pairedItem: { item: i },
  };
});
